t.script:
(function () {
  const configEl = document.getElementById('chapel-schedule-config');
  const schedulesUrl = configEl ? configEl.dataset.schedulesUrl : '/shop/chapel/schedules';
  const chapelSelect = document.querySelector('select[name="chapel_id"]');
  const dateStartInput = document.querySelector('#date_start');
  const dateEndInput = document.querySelector('#date_end');
  const addQtyInput = document.querySelector('input[name="add_qty"]:not(#intention-add-qty)');
  const addQtyHidden = document.querySelector('#intention-add-qty');
  const dateRangeListInput = document.querySelector('#date-range-list');
  const scheduleSelect = document.querySelector('#chapel-schedule-select');
  const statusEl = document.getElementById('chapel-schedule-status');

  if (!chapelSelect || !dateStartInput || !dateEndInput || !scheduleSelect || !statusEl) {
    return;
  }

  const dayNames = ['lunes', 'martes', 'miercoles', 'jueves', 'viernes', 'sabado', 'domingo'];

  const setStatus = (message, isError = false) => {
    statusEl.textContent = message;
    statusEl.classList.toggle('text-danger', isError);
    statusEl.classList.toggle('text-muted', !isError);
  };

  function resetSelect(message, isError = false) {
    scheduleSelect.innerHTML = '<option value="">-- Selecciona un horario --</option>';
    scheduleSelect.disabled = true;
    scheduleSelect.required = false;
    setStatus(message, isError);
  }

  function renderSchedules(items) {
    scheduleSelect.innerHTML = '';
    const placeholder = document.createElement('option');
    placeholder.value = '';
    placeholder.textContent = '-- Selecciona un horario --';
    scheduleSelect.appendChild(placeholder);

    if (!items || !items.length) {
      resetSelect('No hay horarios comunes para el rango seleccionado.', true);
      return;
    }

    setStatus('Selecciona un horario disponible:');
    items.forEach((item) => {
      const opt = document.createElement('option');
      opt.value = item.id;
      const time = [item.start_time, item.end_time].filter(Boolean).join(' - ');
      const priest = item.father_name ? ` — ${item.father_name}` : '';
      opt.textContent = `${time}${priest}`;
      scheduleSelect.appendChild(opt);
    });
    scheduleSelect.disabled = false;
    scheduleSelect.required = true;
  }

  function parseDate(dateStr) {
    if (!dateStr) {
      return null;
    }
    const parsed = new Date(`${dateStr}T00:00:00`);
    return Number.isNaN(parsed.getTime()) ? null : parsed;
  }

  function formatDate(dateObj) {
    const year = dateObj.getFullYear();
    const month = String(dateObj.getMonth() + 1).padStart(2, '0');
    const day = String(dateObj.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  }

  function buildDateRange(startStr, endStr) {
    const start = parseDate(startStr);
    const end = parseDate(endStr || startStr);
    if (!start || !end || end < start) {
      if (dateRangeListInput) {
        dateRangeListInput.value = '';
      }
      return [];
    }

    const dates = [];
    const cursor = new Date(start.getTime());
    while (cursor <= end) {
      dates.push(formatDate(cursor));
      cursor.setDate(cursor.getDate() + 1);
    }
    if (dateRangeListInput) {
      dateRangeListInput.value = dates.join(',');
    }
    return dates;
  }

  function getAddQty() {
    const raw = addQtyInput
      ? parseInt(addQtyInput.value, 10)
      : parseInt(addQtyHidden && addQtyHidden.value ? addQtyHidden.value : '', 10);
    return Number.isFinite(raw) && raw > 0 ? raw : 1;
  }

  function syncHiddenQty() {
    if (addQtyHidden) {
      addQtyHidden.value = getAddQty();
    }
  }

  async function fetchSchedulesByDate(chapelId, dateStr) {
    const parsedDate = parseDate(dateStr);
    const jsDay = parsedDate ? parsedDate.getDay() : null; // domingo=0 ... sábado=6
    const weekdayIdx = jsDay !== null ? (jsDay + 6) % 7 : null; // lunes=0 ... domingo=6
    const weekdayName = weekdayIdx !== null ? dayNames[weekdayIdx] : null;

    const res = await fetch(schedulesUrl, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Accept': 'application/json',
        'X-Requested-With': 'XMLHttpRequest',
      },
      body: JSON.stringify({
        chapel_id: chapelId,
        date_only: weekdayName || dateStr,
        date_value: dateStr,
      }),
    });

    if (!res.ok) {
      throw new Error('Error al consultar horarios');
    }
    const data = await res.json();
    return data.schedules || [];
  }

  function intersectSchedules(scheduleLists) {
    if (!scheduleLists.length) {
      return [];
    }

    const keyFor = (item) => `${item.start_time || ''}__${item.end_time || ''}`;
    const [first, ...rest] = scheduleLists;
    const baseMap = new Map();

    first.forEach((item) => {
      const key = keyFor(item);
      if (!baseMap.has(key)) {
        baseMap.set(key, item);
      }
    });

    const validKeys = Array.from(baseMap.keys()).filter((key) =>
      rest.every((list) => list.some((item) => keyFor(item) === key))
    );

    return validKeys.map((key) => baseMap.get(key));
  }

  async function loadSchedules() {
    resetSelect('Selecciona una capilla y rango de fechas para ver los horarios de misa.');
    syncHiddenQty();
    if (dateRangeListInput) {
      dateRangeListInput.value = '';
    }

    const chapelId = chapelSelect.value;
    const startStr = dateStartInput.value;
    const endStr = dateEndInput.value || startStr;

    if (!chapelId || !startStr || !endStr) {
      return;
    }

    const dates = buildDateRange(startStr, endStr);
    if (!dates.length) {
      resetSelect('Selecciona un rango de fechas válido.', true);
      return;
    }

    const qtyLimit = getAddQty();
    if (qtyLimit && dates.length > qtyLimit) {
      resetSelect(`Selecciona hasta ${qtyLimit} día(s) según la cantidad elegida.`, true);
      return;
    }

    setStatus('Cargando horarios...');
    scheduleSelect.disabled = true;

    try {
      const schedulesPerDay = await Promise.all(
        dates.map((dateStr) => fetchSchedulesByDate(chapelId, dateStr))
      );
      const matching = intersectSchedules(schedulesPerDay);
      renderSchedules(matching);
    } catch (err) {
      console.error(err);
      resetSelect('No se pudieron cargar los horarios. Intenta de nuevo.', true);
    }
  }

  resetSelect('Selecciona una capilla y rango de fechas para ver los horarios de misa.');
  chapelSelect.addEventListener('change', loadSchedules);
  dateStartInput.addEventListener('change', loadSchedules);
  dateEndInput.addEventListener('change', loadSchedules);
  if (addQtyInput) {
    const handleQty = () => {
      syncHiddenQty();
      loadSchedules();
    };
    addQtyInput.addEventListener('change', handleQty);
    addQtyInput.addEventListener('input', handleQty);
    syncHiddenQty();
  } else {
    syncHiddenQty();
  }
})();
